<?php
if(!defined('ABSPATH'))exit;
function eicr_update_service_price($service_id,$price_key,$regular_key,$new_price){
 $service_id=absint($service_id);if(get_post_type($service_id)!=='eicr_service')return;
 $old=get_post_meta($service_id,$price_key,true);$old=is_numeric($old)?(float)$old:0.0;
 if($new_price===''){delete_post_meta($service_id,$price_key);delete_post_meta($service_id,$regular_key);return;}
 $new=min(100000,max(0.01,round((float)$new_price,2)));
 if($old>0&&$new<$old){$regular=get_post_meta($service_id,$regular_key,true);$regular=is_numeric($regular)?(float)$regular:0.0;update_post_meta($service_id,$regular_key,max($regular,$old));}
 elseif($old>0&&$new>$old){delete_post_meta($service_id,$regular_key);}
 update_post_meta($service_id,$price_key,$new);
}
function eicr_service_price_state($service_id,$commercial=false){$price_key=$commercial?'_eicr_commercial_price':'_eicr_price';$regular_key=$commercial?'_eicr_commercial_regular_price':'_eicr_regular_price';$current=(float)get_post_meta($service_id,$price_key,true);$regular=(float)get_post_meta($service_id,$regular_key,true);if($regular<=$current)$regular=0;return['current'=>$current,'regular'=>$regular,'discount'=>$regular>$current&&$current>0?round((($regular-$current)/$regular)*100):0];}
function eicr_service_price_html($service_id,$prefix='From ',$commercial=false){$state=eicr_service_price_state($service_id,$commercial);if($state['current']<=0)return'';$current='£'.number_format_i18n($state['current'],2);if(!$state['regular'])return'<span class="eicr-current-price">'.esc_html($prefix.$current).'</span>';return'<span class="eicr-discount-price"><del aria-label="Previous price">£'.esc_html(number_format_i18n($state['regular'],2)).'</del><strong>'.esc_html($prefix.$current).'</strong><small>'.esc_html($state['discount']).'% OFF</small></span>';}
function eicr_service_price_by_slug_html($slug,$prefix='From ',$commercial=false){$service=eicr_booking_service_by_slug($slug);return $service?eicr_service_price_html($service->ID,$prefix,$commercial):'';}

add_action('admin_menu',function(){add_submenu_page('eicr-control','Prices & Discounts','Prices & Discounts','manage_options','eicr-prices','eicr_prices_admin_page');},25);
function eicr_prices_admin_page(){if(!current_user_can('manage_options'))return;$services=eicr_services();$saved=isset($_GET['prices_saved']);echo'<div class="wrap eicr-admin-wrap"><h1>Prices &amp; Discounts</h1><p>Change every service price from one page. If you reduce a price, the previous price and discount will appear automatically. If you increase it, the discount will be removed.</p>';if($saved)echo'<div class="notice notice-success is-dismissible"><p>Prices saved. Website cards and booking totals now use the updated prices.</p></div>';echo'<form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="eicr_save_all_prices">';wp_nonce_field('eicr_save_all_prices');echo'<div class="eicr-price-table-wrap"><table class="widefat striped eicr-price-table"><thead><tr><th>Service</th><th>Residential price (£)</th><th>Commercial price (£)</th><th>Website display</th></tr></thead><tbody>';foreach($services as$s){$res=eicr_service_price_state($s->ID);$com=eicr_service_price_state($s->ID,true);echo'<tr><td><strong>'.esc_html($s->post_title).'</strong></td><td><input type="number" min="0.01" max="100000" step="0.01" name="prices['.esc_attr($s->ID).'][residential]" value="'.esc_attr(number_format($res['current'],2,'.','')).'" required></td><td><input type="number" min="0.01" max="100000" step="0.01" name="prices['.esc_attr($s->ID).'][commercial]" value="'.esc_attr($com['current']>0?number_format($com['current'],2,'.',''):'').'" placeholder="Automatic"></td><td>'.eicr_service_price_html($s->ID).($com['current']>0?'<br><small>Commercial: '.eicr_service_price_html($s->ID,'From ',true).'</small>':'').'</td></tr>';}echo'</tbody></table></div>';submit_button('Save all prices');echo'</form></div><style>.eicr-price-table-wrap{max-width:1050px;overflow:auto;margin-top:20px}.eicr-price-table th,.eicr-price-table td{vertical-align:middle;padding:12px}.eicr-price-table input{width:150px}.eicr-discount-price{display:inline-flex;align-items:center;gap:7px;flex-wrap:wrap}.eicr-discount-price del{color:#64748b}.eicr-discount-price strong{color:#111827}.eicr-discount-price small{background:#dcfce7;color:#166534;padding:3px 7px;border-radius:999px;font-weight:700}@media(max-width:782px){.eicr-price-table input{width:120px}}</style>';}
add_action('admin_post_eicr_save_all_prices',function(){if(!current_user_can('manage_options'))wp_die('You are not allowed to change prices.');check_admin_referer('eicr_save_all_prices');$rows=isset($_POST['prices'])&&is_array($_POST['prices'])?wp_unslash($_POST['prices']):[];foreach($rows as$id=>$row){$id=absint($id);if(get_post_type($id)!=='eicr_service'||!is_array($row))continue;$res=isset($row['residential'])&&$row['residential']!==''?(float)$row['residential']:'';$com=isset($row['commercial'])&&$row['commercial']!==''?(float)$row['commercial']:'';eicr_update_service_price($id,'_eicr_price','_eicr_regular_price',$res);eicr_update_service_price($id,'_eicr_commercial_price','_eicr_commercial_regular_price',$com);}wp_safe_redirect(add_query_arg(['page'=>'eicr-prices','prices_saved'=>1],admin_url('admin.php')));exit;});